pg.click('#tabs button[data-t="dfs"]'); pg.wait_for_timeout(1500)
print('DFS tab: sport', pg.evaluate('dfsSport'), '| switch hidden:', pg.evaluate('document.querySelector("#dfs-sport").classList.contains("hide")'), '| built:', pg.inner_text('#dfs-built'))
print('slates:', pg.eval_on_selector_all('#dfs-slate option', 'els => els.map(o => o.textContent)'))
print('cash lineup:', pg.inner_text('#dfs-lineup').replace('\n', ' | ')[:900])
pg.click('#dfs-mode button[data-m="gpp"]'); pg.wait_for_timeout(300); print('gpp lineup:', pg.inner_text('#dfs-lineup').replace('\n', ' | ')[:500]); print('count:', pg.inner_text('#dfs-count'))
pg.screenshot(path='dfs_mlb.png', full_page=True)
pg.click('#dfs-shuffle'); pg.wait_for_timeout(200); print('after shuffle:', pg.inner_text('#dfs-count'))
pg.select_option('#dfs-slate', '1'); pg.wait_for_timeout(300); print('showdown:', pg.inner_text('#dfs-lineup').replace('\n', ' | ')[:300])
print('how text shown (mlb/nfl):', pg.evaluate('[document.querySelector("#dfs-how-mlb").style.display, document.querySelector("#dfs-how-nfl").style.display]'))
